/// <summary>
/// Parm method for warehouse
/// </summary>
/// <param name = "_inventLocationId">InventLocationId</param>
/// <returns>Warehouse</returns>
[DataMember(identifierStr(InventLocationId)), BusinessEventsDataMember("Warehouse")]
public InventLocationId paramInventLocationId(InventLocationId _inventLocationId = inventLocationId)
{
    inventLocationId = _inventLocationId;

    return inventLocationId;
}

/// <summary>
/// Parm method for datetime
/// </summary>
/// <param name = "_dateTime">datetime</param>
/// <returns>datetime</returns>
[DataMember(identifierStr(utcdatetime)), BusinessEventsDataMember("utcdatetime")]
public utcdatetime paramDateTime(utcdatetime _dateTime = dateTime)
{
    dateTime = _dateTime;

    return dateTime;
}

/// <summary>
/// Initialize the data contract
/// </summary>
/// <param name = "_inventLocationId">InventLocationId</param>
private void initialize(InventLocationId _inventLocationId)
{
    inventLocationId = _inventLocationId;
}

/// <summary>
/// Create contract instance using warehouse
/// </summary>
/// <param name = "_inventLocationId">InventLocationId</param>
/// <returns>An instance of <c>METProcessBOHFileContactClass</c></returns>
public static METProcessBOHFileContactClass newFromWarehouse(InventLocationId _inventLocationId)
{
    var contract = new METProcessBOHFileContactClass();
    contract.initialize(_inventLocationId);

    return contract;
}
